def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        category = row["category"].strip().lower()
        amount_str = row["amount"].strip()

        # Skip empty category
        if not category:
            continue

        # Skip empty or non-numeric amount
        if not amount_str:
            continue

        try:
            amount = float(amount_str)
        except ValueError:
            continue

        # Add to totals (summing)
        if category in totals:
            totals[category] += amount
        else:
            totals[category] = amount

    # Round each total to 2 decimal places
    for category in totals:
        totals[category] = round(totals[category], 2)

    return totals
